starter.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int p = in.nextInt();
        if (p <= 60) {
            System.out.println(1);
        } else if (p <= 75) {
            System.out.println(2);
        } else if (p <= 90) {
            System.out.println(3);
        } else {
            System.out.println(4);
        }
    }
}

starter.cpp:
#include <iostream>
using namespace std;

int main() {
    int p;
    cin >> p;
    if (p <= 60) {
        cout << 1 << endl;
    } else if (p <= 75) {
        cout << 2 << endl;
    } else if (p <= 90) {
        cout << 3 << endl;
    } else {
        cout << 4 << endl;
    }
    return 0;
}

